package com.luminor.tavernquest.feature.quest.detail
import androidx.compose.foundation.layout.*;import androidx.compose.material3.Text;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import androidx.hilt.navigation.compose.hiltViewModel
@Composable fun QuestDetailScreen(vm:QuestDetailViewModel=hiltViewModel(),onBack:()->Unit,onComplete:(String)->Unit){val s by vm.ui.collectAsState();val q=s.quest;Column(Modifier.fillMaxSize().padding(24.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){if(q==null)Text("Carregando contrato...")else{Text(q.template.title);Text(q.template.description);Text(q.template.category.title);Text("Recompensa: ${q.template.xpReward} XP");s.message?.let{Text(it)};QuestActions(q.status,vm::accept,{onComplete(q.id)},onBack)}}}
